SELECT d.*,u.username as uName FROM (
SELECT * FROM u_daily_flow


        AND made = #{id}


) d
LEFT JOIN sys_user u ON d.made = u.id
ORDER BY record_time DESC

SELECT d.*,u.username as uName FROM (SELECT * FROM u_daily_flow


        AND  DATE_FORMAT(record_time, '%Y-%m-%d') BETWEEN #{searchDate1} AND #{searchDate2}


        AND `type` = #{searchType}


        AND `made` = #{searchName}


        AND `cost` >= #{minCost}


        AND `cost` <= #{maxCost}  


 ) d
LEFT JOIN sys_user u ON d.made = u.id
ORDER BY record_time DESC

SELECT * FROM u_daily_flow
WHERE
made = #{userId}



        AND 1=1



        AND YEAR(record_time) = #{year}



        AND YEAR(record_time) = #{year}
        AND MONTH(record_time) = #{month}



        AND record_time BETWEEN #{startDate} AND #{endDate}



        AND record_time >= DATE_SUB(CURDATE(), INTERVAL 30 DAY)


ORDER BY record_time ASC, create_time ASC

SELECT type_tag_id as consumption_type,SUM(cost) as consumption_cost FROM u_daily_flow_info WHERE daily_flow_id in (
SELECT id FROM (
        SELECT *
        FROM u_daily_flow
        WHERE `type` = #{consumptionType} AND record_time = DATE_FORMAT(#{consumptionTime} , '%Y-%m-%D') AND made = #{queryId}
    ) AS temp
) GROUP BY type_tag_id ORDER BY consumption_cost DESC

SELECT type_tag_id as consumption_type,SUM(cost) as consumption_cost FROM u_daily_flow_info WHERE daily_flow_id in (
SELECT id FROM u_daily_flow
WHERE `type` = #{consumptionType} AND DATE_FORMAT(record_time, '%Y-%m') = DATE_FORMAT(#{consumptionTime}, '%Y-%m') AND made = #{queryId}
) GROUP BY type_tag_id ORDER BY consumption_cost DESC

SELECT type_tag_id as consumption_type,SUM(cost) as consumption_cost FROM u_daily_flow_info WHERE daily_flow_id in (
SELECT id FROM u_daily_flow
WHERE `type` = #{consumptionType} AND DATE_FORMAT(record_time , '%Y') = DATE_FORMAT(#{consumptionTime} , '%Y') AND made = #{queryId}
) GROUP BY type_tag_id ORDER BY consumption_cost DESC

